+  font-size: 0.98rem;
+  color: var(--text-main);
+  line-height: 1.5;
+}
+
+.check-icon {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 24px;
+  height: 24px;
+  border-radius: 50%;
+  background-color: var(--accent);
+  color: var(--primary);
+  font-weight: 700;
+  font-size: 0.85rem;
+  margin-right: 0.75rem;
+  flex-shrink: 0;
+}
+
+/* Services Section */
+.section-services {
+  background-color: var(--bg-services);
+  position: relative;
+}
+
+.card-service {
+  background-color: var(--bg-surface);
+  border: 1px solid var(--card-border);
+  border-top: 4px solid var(--primary);
+  border-radius: 12px;
+  height: 100%;
+  min-height: 170px;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  transition: transform 0.25s ease, box-shadow 0.25s ease;
+  box-shadow: 0 4px 16px rgba(10, 25, 47, 0.05);
+}
+
+.card-service:hover {
+  transform: translateY(-4px);
+  box-shadow: 0 12px 28px rgba(30, 58, 138, 0.14);
+}
+
+.card-service h6 {
+  color: var(--dark);
+  font-size: 1.05rem;
+  min-height: 2.6rem;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  margin-bottom: 0.5rem;
+}
+
+.card-service p {
+  color: var(--text-muted);
+  line-height: 1.5;
+}
+
+/* Testimonials */
+.section-testimonial {
+  background-color: var(--bg-surface);
+  position: relative;
+}
+
+.testimonial-card {
+  background-color: var(--bg-app);
+  border: 1px solid var(--card-border);
+  box-shadow: 0 6px 20px rgba(10, 25, 47, 0.04);
+}
+
+.testimonial-card p.fs-4 {
+  color: var(--dark);
+  font-family: var(--font-headings);
+  line-height: 1.5;
+  font-weight: 500;
+}
+
+/* Contact / Dark Hero Section */
+.hero-dark {
+  background-color: var(--dark);
+  color: #ffffff;
+  position: relative;
+}
+
+.hero-dark h2 {
+  font-size: clamp(1.9rem, 4vw, 2.5rem);
+}
+
+/* Footer */
+.app-footer {
+  background-color: var(--dark-surface);
+  color: #ffffff;
+  border-top: 1px solid rgba(255, 255, 255, 0.06);
+}
+
+/* Global Images & Badges */
+img {
+  max-width: 100%;
+  height: auto;
+}
+
+.badge-theme {
+  background-color: var(--primary);
+  display: inline-block;
+  padding: 6px 14px;
+  border-radius: 20px;
+  font-size: 0.85rem;
+  color: #ffffff;
+}
+
+/* Responsive adjustments */
+@media (max-width: 767.98px) {
+  .hero-img,
+  .about-img {
+    height: 260px;
+    max-width: 100%;
+    margin-top: 0.5rem;
+  }
+
+  .card-service {
+    min-height: auto;
+    padding: 1.5rem !important;
+  }
+
+  .card-service h6 {
+    min-height: auto;
+  }
+
+  .hero .btn-brand,
+  .hero-dark .btn-brand {
+    width: 100%;
+  }
+}

input.command:
node -e "
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const tags = [];
const regex = /<\/?([a-zA-Z0-9]+)(\s+[^>]*)?\/?>/g;
let match;
const voidTags = new Set(['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']);
while ((match = regex.exec(html)) !== null) {
  const full = match[0];
  const tag = match[1].toLowerCase();
  const isClosing = full.startsWith('</');
  const isSelfClosing = full.endsWith('/>') || voidTags.has(tag);
  if (isClosing) {
    const last = tags.pop();
    if (last !== tag) {
      console.log('Mismatch! expected', last, 'got', tag);
    }
  } else if (!isSelfClosing) {
    tags.push(tag);
  }
}
console.log('Unclosed tags:', tags);
"

