const fs = require('fs');
const css = fs.readFileSync('css/style.css', 'utf8');
let openBraces = 0;
for (const char of css) {
  if (char === '{') openBraces++;
  if (char === '}') openBraces--;
}
console.log('Open braces remaining:', openBraces);
"

